/**
 * The 6-digit code generated by the server for a new account or an approved
 * password reset. Shown once, in a dialog that cannot be missed, so that the
 * administrator (or the Super Admin) hands it over in person.
 */
export default function GeneratedCredentialModal({ credential, onClose }: { credential: { name: string; username: string; password: string }; onClose: () => void }) {
  return <div className="fixed inset-0 z-[100001] grid place-items-center overflow-y-auto overscroll-contain bg-slate-950/60 p-3 backdrop-blur-sm sm:p-6">
    <div role="dialog" aria-modal="true" className="my-auto max-h-[calc(100dvh-1.5rem)] w-full max-w-md overflow-y-auto rounded-2xl border border-aulia-teal/30 bg-white p-5 shadow-2xl dark:bg-slate-950 sm:p-6">
      <p className="text-xs font-bold uppercase tracking-[.2em] text-aulia-teal">Code d’accès</p>
      <h2 className="mt-2 text-xl font-semibold text-slate-900 dark:text-white">Code pour {credential.name}</h2>
      <p className="mt-2 text-sm leading-6 text-slate-600 dark:text-slate-300">Remettez ce code à la personne elle-même, après avoir vérifié son identité. Il reste affiché dans « Codes d’accès à remettre » jusqu’à ce qu’elle l’ait utilisé. Elle se connecte avec son identifiant et ce code, puis choisit aussitôt son propre mot de passe. Le code est annulé après 5 essais erronés.</p>
      <dl className="mt-5 space-y-3 rounded-xl bg-aulia-mist p-4 text-sm text-aulia-navy dark:bg-slate-900 dark:text-slate-100"><div><dt className="text-xs font-semibold uppercase opacity-70">Utilisateur</dt><dd className="mt-1 font-bold">{credential.username}</dd></div><div><dt className="text-xs font-semibold uppercase opacity-70">Code à 6 chiffres</dt><dd className="mt-1 break-all font-mono text-2xl font-bold tracking-[.3em]">{credential.password}</dd></div></dl>
      <button type="button" onClick={onClose} className="mt-6 w-full rounded-xl bg-aulia-navy px-4 py-3 text-sm font-semibold text-white">Fermer</button>
    </div>
  </div>;
}
